const raw = $json.body ?? $json;

const src = {};

for (const [key, value] of Object.entries(raw)) {
  src[key.trim()] = value;
}
return [{
  json: {
    alert_id: String(src.alert_id ?? '').trim(),
    timestamp: String(src.timestamp ?? '').trim(),
    source: String(src.source ?? '').trim().toLowerCase(),
    alert_type: String(src.alert_type ?? '').trim().toLowerCase(),
    description: String(src.description ?? '').trim(),

    source_ip: String(src.source_ip ?? '').trim(),
    destination_ip: String(src.destination_ip ?? '').trim(),
    domain: String(src.domain ?? '').trim().toLowerCase(),
    url: String(src.url ?? '').trim(),
    file_hash: String(src.file_hash ?? '').trim().toLowerCase(),
    username: String(src.username ?? '').trim(),
    hostname: String(src.hostname ?? '').trim(),
    original_severity: String(src.original_severity ?? '').trim().toLowerCase(),

    metadata:
      src.metadata &&
      typeof src.metadata === 'object'
        ? src.metadata
        : {},

    input_source: $json.body ? 'webhook' : 'manual'
  }
}];

const requiredFields = [
  'alert_id',
  'timestamp',
  'source',
  'alert_type',
  'description'
];

const errors = [];

for (const field of requiredFields) {
  if (!$json[field]) {
    errors.push(`Missing required field: ${field}`);
  }
}

if (
  $json.timestamp &&
  Number.isNaN(Date.parse($json.timestamp))
) {
  errors.push('timestamp must be a valid date/time');
}

return [{
  json: {
    ...$json,

    validation: {
      valid: errors.length === 0,
      errors
    }
  }
}];

return [
  {
    json: {
      ...$json,
      status: "rejected",
      message: "Invalid AdvSOC security-alert payload",
      errors: $json.validation?.errors ?? []
    }
  }
];

const text = [
  $json.description,
  $json.source_ip,
  $json.destination_ip,
  $json.domain,
  $json.url,
  $json.file_hash
]
.filter(Boolean)
.join(' ');

// IPv4 candidates
const ipCandidates =
  text.match(/\b(?:\d{1,3}\.){3}\d{1,3}\b/g) ?? [];

// Validate each octet
const ips = ipCandidates.filter(ip =>
  ip.split('.').every(part => {
    const n = Number(part);
    return n >= 0 && n <= 255;
  })
);

// URLs
const urls =
  text.match(/\bhttps?:\/\/[^\s<>"']+/gi) ?? [];

// Domains
const domains = [];

if ($json.domain) {
  domains.push($json.domain.toLowerCase());
}

for (const url of urls) {
  try {
    domains.push(new URL(url).hostname.toLowerCase());
  } catch {}
}

const descriptionDomains =
  ($json.description ?? '').match(
    /\b(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,63}\b/gi
  ) ?? [];

domains.push(...descriptionDomains.map(x => x.toLowerCase()));

// MD5 / SHA-1 / SHA-256
const hashes =
  text.match(
    /\b(?:[A-Fa-f0-9]{64}|[A-Fa-f0-9]{40}|[A-Fa-f0-9]{32})\b/g
  ) ?? [];

const unique = arr => [...new Set(arr)];

return [{
  json: {
    ...$json,

    iocs: {
      ips: unique(ips),
      domains: unique(domains),
      urls: unique(urls),
      hashes: unique(hashes.map(x => x.toLowerCase()))
    }
  }
}];

const description = ($json.description ?? '').toLowerCase();
const alertType = ($json.alert_type ?? '').toLowerCase();
const username = ($json.username ?? '').toLowerCase();
const originalSeverity =
  ($json.original_severity ?? '').toLowerCase();

const text = `${alertType} ${description}`;

let score = 0;
const matchedRules = [];

function addRule(id, points, evidence) {
  score += points;

  matchedRules.push({
    rule: id,
    points,
    evidence
  });
}

// --------------------
// Authentication
// --------------------

const failedMatch = description.match(
  /(\d+)\s+(?:failed|unsuccessful)\s+(?:login|logins|authentication attempts?)/
);

if (failedMatch) {
  const attempts = Number(failedMatch[1]);

  if (attempts >= 20) {
    addRule(
      'AUTH_HIGH_VOLUME_FAILURES',
      25,
      `${attempts} failed authentication attempts`
    );
  } else if (attempts >= 5) {
    addRule(
      'AUTH_REPEATED_FAILURES',
      10,
      `${attempts} failed authentication attempts`
    );
  }
}

if (
  /brute[\s-]?force|password spraying|password spray/.test(text)
) {
  addRule(
    'AUTH_BRUTE_FORCE_LANGUAGE',
    25,
    'Alert explicitly indicates brute-force or password-spraying activity'
  );
}

if (
  /successful login|successfully authenticated/.test(text) &&
  /failed login|brute[\s-]?force|password spray/.test(text)
) {
  addRule(
    'AUTH_SUCCESS_AFTER_FAILURES',
    20,
    'Successful authentication occurred after suspicious failures'
  );
}

// --------------------
// Privileged account
// --------------------

if (
  /admin|administrator|privileged|\broot\b/.test(
    `${username} ${description}`
  )
) {
  addRule(
    'PRIVILEGED_IDENTITY',
    20,
    'Privileged account or identity involved'
  );
}

// --------------------
// Malware
// --------------------

if (
  /malware|ransomware|trojan|malicious executable|known malicious file/.test(
    text
  )
) {
  addRule(
    'MALWARE_INDICATOR',
    45,
    'Alert indicates malicious file or malware activity'
  );
}

// --------------------
// Phishing
// --------------------

if (
  /phishing|credential harvesting|credential-harvesting/.test(text)
) {
  addRule(
    'PHISHING_INDICATOR',
    30,
    'Alert contains phishing-related evidence'
  );
}

// --------------------
// Reconnaissance
// --------------------

if (
  /port scan|port scanning|reconnaissance|enumeration/.test(text)
) {
  addRule(
    'RECON_ACTIVITY',
    20,
    'Reconnaissance or scanning behavior detected'
  );
}

// --------------------
// C2 / exfiltration
// --------------------

if (
  /command[\s-]and[\s-]control|\bc2\b|data exfiltration|exfiltration/.test(
    text
  )
) {
  addRule(
    'C2_OR_EXFILTRATION',
    50,
    'Command-and-control or exfiltration evidence detected'
  );
}

// --------------------
// Original severity
// --------------------

const severityWeights = {
  medium: 5,
  high: 10,
  critical: 15
};

if (severityWeights[originalSeverity]) {
  addRule(
    'SOURCE_SEVERITY',
    severityWeights[originalSeverity],
    `Source marked alert as ${originalSeverity}`
  );
}

// Do not allow deterministic rules alone
// to produce the final 100-point verdict.
score = Math.min(score, 60);

// --------------------
// Preliminary category
// --------------------

let category = 'other_unknown';

if (
  /command[\s-]and[\s-]control|\bc2\b|exfiltration/.test(text)
) {
  category = 'malicious_network_activity';

} else if (
  /malware|ransomware|trojan|malicious executable/.test(text)
) {
  category = 'malware_malicious_file';

} else if (
  /phishing|credential harvesting/.test(text)
) {
  category = 'phishing_malicious_url';

} else if (
  /login|authentication|brute[\s-]?force|password spray/.test(text)
) {
  category = 'suspicious_authentication';

} else if (
  /port scan|port scanning|reconnaissance|enumeration/.test(text)
) {
  category = 'reconnaissance_scanning';

} else if (
  score === 0 &&
  originalSeverity === 'low'
) {
  category = 'benign_informational';
}

return [{
  json: {
    ...$json,

    rule_result: {
      preliminary_category: category,
      rule_score: score,
      matched_rules: matchedRules
    }
  }
}];
